interface Wallet { fun deposit(cents: Long) }            // public contract

internal class WalletImpl(                             // module-only implementation
    private val ledger: Ledger,
) : Wallet {
    override fun deposit(cents: Long) = ledger.append(cents)
}

fun wallet(ledger: Ledger): Wallet = WalletImpl(ledger) // only the interface escapes
